budget.code:
def budget(sdk):
    state = sdk.get_state()
    return max(0, min(400, state["max_steps"]) - state["steps_used"])

grip.code:
def grip(sdk, action, steps):
    available = budget(sdk)
    if available > 0:
        return sdk.set_gripper(action, steps=min(steps, available))
    return {"grasped_hint": False}

move.code:
def move(sdk, position, yaw, action, steps, tolerance):
    available = budget(sdk)
    if available > 0:
        return sdk.move_to(
            position,
            yaw=wrap_angle(yaw),
            gripper=action,
            max_steps=min(steps, available),
            tol=tolerance,
        )
    return {"reached": False}

seated.code:
def seated(state, floor):
    nut = state["objects"]["nut"]
    goal = state["goal_pos"]
    return (
        hypot(nut["pos"][0] - goal[0], nut["pos"][1] - goal[1]) < 0.008
        and abs(nut["pos"][2] - floor) < 0.016
        and abs(square_error(nut["yaw"])) < 0.075
        and upright(nut) > 0.975
    )

upright.code:
def upright(nut):
    quat = nut["quat"]
    return 1.0 - 2.0 * (quat[0] ** 2 + quat[1] ** 2)

policy_budget.code:
def policy_budget(sdk, requested, reserve=0):
    state = sdk.get_state()
    return max(0, min(requested, state["max_steps"] - state["steps_used"] - reserve))

policy_move.code:
def policy_move(sdk, target, yaw, gripper, steps, reserve=0, tol=0.012):
    budget = policy_budget(sdk, steps, reserve)
    if budget > 0:
        sdk.move_to(
            target, yaw=yaw, gripper=gripper, max_steps=budget, tol=tol
        )
    state = sdk.get_state()
    return policy_distance(state["eef_pos"], target)
